### Python

```python
def max_distinct_marks(marks):
    MAX_MASK = 1023
    SIZE = 1024
    g = [MAX_MASK] * SIZE      # g[mask] 表示包含 mask 的所有初始标记的按位与
    exist = [False] * SIZE

    for x in marks:
        g[x] = x
        exist[x] = True

    # 超集 DP
    for bit in range(10):
        for mask in range(SIZE):
            if (mask & (1 << bit)) == 0:
                super_mask = mask | (1 << bit)
                if exist[super_mask]:
                    g[mask] &= g[super_mask]
                    exist[mask] = True

    ans = sum(1 for mask in range(SIZE) if exist[mask] and g[mask] == mask)
    return ans

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    it = iter(data)
    t = int(next(it))
    out = []
    for _ in range(t):
        n = int(next(it))
        marks = [int(next(it)) for _ in range(n)]
        out.append(str(max_distinct_marks(marks)))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
